"""Pellet sales page, matched to the current PelletsGrupp offer."""
import json
from pathlib import Path

TYPES=json.loads((Path(__file__).resolve().parent/'data/pellets.json').read_text())
def page(extra=''):
 cards=[]
 for p in TYPES:
  specs={'Диаметр гранулы':'8 мм','Зольность':p['ash'],'Длина гранулы':'10–30 мм','Насыпная плотность':'650 кг/м³','Прочность':'99,2%','Теплотворность':p['heat']}
  rows=''.join(f'<tr><th scope="row">{k}</th><td>{v}</td></tr>' for k,v in specs.items())
  price=f'{p["price"]:,}'.replace(',','\u202f')
  cards.append(f'<article class="pellet-card" id="{p["id"]}"><div class="pellet-top"><img src="{p["image"]}" alt="{p["name"]}"><div><span class="badge">{p["category"]}</span><h2>{p["name"]}</h2><p class="sku-line">Артикул: <span>{p["sku"]}</span></p><p class="pellet-price">{price} ₽<span>/ тонна</span></p></div></div><table class="specs"><tbody>{rows}</tbody></table><p class="pellet-pack">Фасовка: мешки по <strong>30 кг</strong> или биг-бэг по <strong>1 т</strong></p><a class="btn" href="tel:+73433455225">Позвонить: +7 (343) 345-52-25</a><p class="fine">Наличие и доставку уточним по телефону.</p></article>')
 delivery=[('01 / САМОВЫВОЗ','Со склада','Фасованные пеллеты со склада в Екатеринбурге: ул. Лукиных, д. 1.'),('02 / ГРУЗОВИК','От 1 до 5 тонн','Доставка пеллет в мешках до адреса клиента с участием наших грузчиков.'),('03 / МАНИПУЛЯТОР','До 5 тонн','Доставка с разгрузкой манипулятором для частных клиентов.'),('04 / ОПТОМ','От 20 тонн','Поставка оптовых партий предприятиям Уральского региона.')]
 delivery_cards=''.join(f'<article class="service"><div class="num">{n}</div><h3>{h}</h3><p>{t}</p></article>' for n,h,t in delivery)
 return '''<div class="wrap crumbs"><a href="/">Главная</a> / Пеллеты</div><div class="wrap"><div class="page-head pellet-heading"><span class="eyebrow">Для дома и бизнеса · поставка со склада</span><h1>Топливные пеллеты</h1><p class="lead">Хвойные древесные гранулы для отопления дома, котельной и предприятия. Выберите вид топлива и удобный способ получения.</p></div><div class="pellet-grid">'''+''.join(cards)+'''</div><p class="fine">Наличие и объём партии согласуем по телефону.</p></div>
<section class="section white" id="delivery"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Получение и доставка</span><h2>От мешка со склада до оптовой партии</h2></div></div><div class="grid cycle-grid">'''+delivery_cards+'''</div><div class="pellet-delivery-note"><div><h3>Стоимость доставки рассчитывается отдельно</h3><p>Для доставки внутри ЕКАД действуют тарифы. Междугороднюю доставку рассчитываем индивидуально с учётом адреса, объёма и способа разгрузки.</p></div><a class="btn" href="tel:+73433455225">Позвонить: +7 (343) 345-52-25</a></div></div></section>
<section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Из хвойного сырья</span><h2>Топливо для вашей системы отопления</h2></div></div><div class="grid"><article class="tile"><h3>Натуральное сырьё</h3><p>Поставляем пеллеты из сухого хвойного сырья без песка, земли и постороннего мусора.</p></article><article class="tile"><h3>Без химических добавок</h3><p>Древесные гранулы получают прессованием хвойного опила без использования вредных химических составов.</p></article><article class="tile"><h3>Подбор под оборудование</h3><p>Поможем выбрать топливо с учётом требований котла, режима работы и необходимого объёма поставки.</p></article></div></div></section>
<section class="section white"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Полный цикл услуг</span><h2>От топлива до сервиса</h2></div></div><div class="grid"><a class="tile" href="/katalog/"><h3>Котлы и горелки</h3><p>Подбор оборудования и комплектации под ваш объект.</p><span class="text-link">Открыть каталог →</span></a><a class="tile" href="/otoplenie/"><h3>Монтаж отопления</h3><p>Расчёт, проектирование, установка и пусконаладка.</p><span class="text-link">Подробнее о монтаже →</span></a><a class="tile" href="/servisiremont/"><h3>Сервис и ремонт</h3><p>ТО, сезонная чистка, настройка автоматики и консультации.</p><span class="text-link">Узнать об услугах →</span></a></div></div></section>'''+extra+'''
<section class="section"><div class="wrap"><div class="cta"><div><h2>Поможем с выбором и поставкой пеллет</h2><p>Согласуем вид топлива, объём партии и способ доставки.</p></div><a class="btn lime" href="tel:+73433455225">Позвонить: +7 (343) 345-52-25</a></div></div></section>'''
